// A plain array in msg.payload REPLACES the complete action list.
// Only "id" and "payload" are required; everything else gets defaults.
msg.payload = [
    { id: 'one',   label: 'One',   icon: 'pi-check', payload: 'one' },
    { id: 'two',   label: 'Two',   icon: 'pi-star',  payload: 'two' },
    { id: 'three', label: 'Three', icon: 'pi-heart', payload: 'three' }
];
return msg;

// The output payload keeps its native type.
msg.payload = [
    { id: 't-string',  label: 'String',        icon: 'pi-font',     payload: 'hello' },
    { id: 't-empty',   label: 'Empty string',  icon: 'pi-minus',    payload: '' },
    { id: 't-int',     label: 'Number 42',     icon: 'pi-hashtag',  payload: 42 },
    { id: 't-float',   label: 'Number -3.14',  icon: 'pi-percentage', payload: -3.14 },
    { id: 't-true',    label: 'Boolean true',  icon: 'pi-check',    payload: true },
    { id: 't-false',   label: 'Boolean false', icon: 'pi-times',    payload: false },
    { id: 't-object',  label: 'Object',        icon: 'pi-box',      payload: { name: 'evening', brightness: 40, nested: { on: true } } },
    { id: 't-array',   label: 'Array',         icon: 'pi-list',     payload: [1, 'two', null, { three: 3 }] },
    { id: 't-null',    label: 'null',          icon: 'pi-ban',      payload: null }
];
return msg;

// "payload: null" is a real value and is sent as null.
// A MISSING payload field is an error (see section 7).
msg.payload = [
    { id: 'null-ok', label: 'Send null', icon: 'pi-ban', payload: null }
];
return msg;

// Every action field in use.
msg.payload = [
    {
        id: 'full-1',
        label: 'Evening scene',
        icon: 'pi-moon',
        tooltip: 'Dim the lights',
        background: '#1e3a8a',   // #rgb, #rrggbb or #rrggbbaa
        color: '#ffffff',
        topic: 'scene',
        payload: { name: 'evening', brightness: 40 },
        visible: true,
        enabled: true
    },
    {
        id: 'full-2',
        label: 'Morning',
        icon: 'pi-sun',
        tooltip: 'Bright and warm',
        background: '#f59e0b',
        color: '#000',
        topic: 'scene',
        payload: { name: 'morning', brightness: 90 }
    }
];
return msg;

// Missing display values come from the node defaults:
// label "Action", icon "pi-circle", tooltip "", no colors, visible, enabled.
msg.payload = [
    { id: 'min-1', payload: 1 },
    { id: 'min-2', payload: 2 }
];
return msg;

// Hidden or disabled actions never produce output (the runtime checks again on click).
msg.payload = [
    { id: 'shown',    label: 'Shown',    icon: 'pi-eye',     payload: 'shown' },
    { id: 'disabled', label: 'Disabled', icon: 'pi-lock',    payload: 'never sent', enabled: false },
    { id: 'hidden',   label: 'Hidden',   icon: 'pi-eye-slash', payload: 'never sent', visible: false }
];
return msg;

// msg.topic is only set on the output when the action has a non-empty topic.
msg.payload = [
    { id: 'topic-yes', label: 'With topic',    icon: 'pi-tag', topic: 'my/topic', payload: 'a' },
    { id: 'topic-no',  label: 'Without topic', icon: 'pi-minus', payload: 'b' }
];
return msg;

// Labels and tooltips are rendered as text, never as HTML.
msg.payload = [
    { id: 'html', label: '<b>bold</b> <img src=x onerror=alert(1)>', tooltip: '<i>tooltip</i>', icon: 'pi-code', payload: 'text only' },
    { id: 'uni',  label: 'Grüße 🌍 日本語', icon: 'pi-globe', payload: 'unicode ok' }
];
return msg;

msg.payload = Array.from({ length: 12 }, (_, i) => ({
    id: 'many-' + (i + 1),
    label: 'Action ' + (i + 1),
    icon: 'pi-star',
    payload: i + 1
}));
return msg;

// An empty array is valid and removes every action.
msg.payload = [];
return msg;

// Only the listed fields change, everything else stays as it is.
msg.payload = { button: { icon: 'pi-bolt', label: 'Quick actions', tooltip: 'Open the quick action menu' } };
return msg;

// Colors are hex only: #rgb, #rrggbb or #rrggbbaa (alpha). "red" would be rejected.
const options = [
    { background: '#dc2626', color: '#ffffff' },
    { background: '#16a34a', color: '#fff' },
    { background: '#7c3aed80', color: '#ffffff' }   // 8 digits: with transparency
];
const i = (context.get('i') || 0) % options.length;
context.set('i', i + 1);
msg.payload = { button: options[i] };
node.status({ text: JSON.stringify(options[i]) });
return msg;

// Empty strings clear label/colors (colors fall back to the default).
msg.payload = { button: { label: '', background: '', color: '' } };
return msg;

const radii = [0, 12, 28, 48];              // 0 to 48
const i = (context.get('i') || 0) % radii.length;
context.set('i', i + 1);
msg.payload = { button: { radius: radii[i] } };
node.status({ text: 'radius ' + radii[i] });
return msg;

// Disabled: still visible, but it can not be opened and no action can fire.
msg.payload = { button: { enabled: false } };
return msg;

// Every position, one per trigger. Centered axes ignore the offset on that axis.
const positions = ['top-left', 'top-center', 'top-right', 'center-left', 'center', 'center-right',
                   'bottom-left', 'bottom-center', 'bottom-right'];
const i = (context.get('i') || 0) % positions.length;
context.set('i', i + 1);
msg.payload = { button: { position: positions[i] } };
node.status({ text: positions[i] });
return msg;

const options = [{ offsetX: 0, offsetY: 0 }, { offsetX: 24, offsetY: 24 }, { offsetX: 120, offsetY: 60 }, { offsetX: 300, offsetY: 200 }];   // 0 to 500 each
const i = (context.get('i') || 0) % options.length;
context.set('i', i + 1);
msg.payload = { button: options[i] };
node.status({ text: JSON.stringify(options[i]) });
return msg;

msg.payload = {
    button: {
        icon: 'pi-cog', label: 'Settings', tooltip: 'Settings',
        background: '#0f766e', color: '#ffffff',
        size: 64, radius: 16,
        visible: true, enabled: true,
        position: 'bottom-right', offsetX: 24, offsetY: 24
    }
};
return msg;

// mode "menu" is always a linear, labelled list.
msg.payload = { menu: { mode: 'menu', direction: 'up' } };
return msg;

// shape and direction must fit together. Send both in the same message.
// linear / semi-circle: up down left right    quarter-circle: up-left up-right down-left down-right
// circle ignores the direction. Pick a matching button position for good looks (e.g. bottom-right + quarter-circle up-left).
const combos = [
    ['linear', 'up'], ['linear', 'down'], ['linear', 'left'], ['linear', 'right'],
    ['semi-circle', 'up'], ['semi-circle', 'down'], ['semi-circle', 'left'], ['semi-circle', 'right'],
    ['quarter-circle', 'up-left'], ['quarter-circle', 'up-right'], ['quarter-circle', 'down-left'], ['quarter-circle', 'down-right'],
    ['circle', 'up']
];
const i = (context.get('i') || 0) % combos.length;
context.set('i', i + 1);
msg.payload = { menu: { mode: 'speed-dial', shape: combos[i][0], direction: combos[i][1] } };
node.status({ text: combos[i].join(' / ') });
return msg;

const radii = [0, 80, 120, 200];            // 0 to 500, only for circle shapes
const i = (context.get('i') || 0) % radii.length;
context.set('i', i + 1);
msg.payload = { menu: { radius: radii[i] } };
node.status({ text: 'radius ' + radii[i] });
return msg;

const options = [{ gap: 0, actionSize: 44 }, { gap: 8, actionSize: 44 }, { gap: 24, actionSize: 64 }, { gap: 48, actionSize: 80 }];   // gap 0-48, actionSize 44-80
const i = (context.get('i') || 0) % options.length;
context.set('i', i + 1);
msg.payload = { menu: options[i] };
node.status({ text: JSON.stringify(options[i]) });
return msg;

const durations = [0, 150, 600, 1000];      // milliseconds; prefers-reduced-motion always wins
const i = (context.get('i') || 0) % durations.length;
context.set('i', i + 1);
msg.payload = { menu: { duration: durations[i] } };
node.status({ text: durations[i] + ' ms' });
return msg;

const on = !context.get('on');
context.set('on', on);
msg.payload = { menu: { closeOnSelect: on } };
node.status({ text: 'closeOnSelect ' + on });
return msg;

const on = !context.get('on');
context.set('on', on);
msg.payload = { menu: { overlay: on } };
node.status({ text: 'overlay ' + on });
return msg;

// Only effective for linear speed-dial (menu mode always shows labels, circle shapes never do).
const on = !context.get('on');
context.set('on', on);
msg.payload = { menu: { showLabels: on } };
node.status({ text: 'showLabels ' + on });
return msg;

const modes = ['light', 'dark', 'auto'];
const i = (context.get('i') || 0) % modes.length;
context.set('i', i + 1);
msg.payload = { theme: { mode: modes[i] } };
node.status({ text: modes[i] });
return msg;

const on = !context.get('on');
context.set('on', on);
msg.payload = { theme: { radius: on ? 24 : 12, shadow: !on, zIndex: on ? 5000 : 2000 } };   // radius 0-40, zIndex 1-10000
node.status({ text: JSON.stringify(msg.payload.theme) });
return msg;

// All four sections in one message. actions replaces the list, the others merge field by field.
msg.payload = {
    actions: [
        { id: 'c-1', label: 'First',  icon: 'pi-home',   payload: 'first' },
        { id: 'c-2', label: 'Second', icon: 'pi-user',   payload: 'second' },
        { id: 'c-3', label: 'Third',  icon: 'pi-cog',    payload: 'third' }
    ],
    button: { icon: 'pi-th-large', label: '', background: '#0ea5e9', position: 'bottom-right' },
    menu: { mode: 'speed-dial', shape: 'linear', direction: 'up', showLabels: true, overlay: true },
    theme: { mode: 'auto', shadow: true }
};
return msg;

msg.payload = {
    actions: Array.from({ length: 6 }, (_, i) => ({ id: 'ring-' + (i + 1), label: 'Item ' + (i + 1), icon: 'pi-star', payload: i + 1 })),
    button: { position: 'center', size: 64, label: '' },
    menu: { mode: 'speed-dial', shape: 'circle', direction: 'up', radius: 0, overlay: true }
};
return msg;

msg.payload = {
    actions: Array.from({ length: 5 }, (_, i) => ({ id: 'arc-' + (i + 1), label: 'Item ' + (i + 1), icon: 'pi-circle', payload: i + 1 })),
    button: { position: 'bottom-center', size: 56, offsetY: 24 },
    menu: { mode: 'speed-dial', shape: 'semi-circle', direction: 'up', radius: 0 }
};
return msg;

msg.payload = {
    actions: Array.from({ length: 4 }, (_, i) => ({ id: 'q-' + (i + 1), label: 'Item ' + (i + 1), icon: 'pi-bookmark', payload: i + 1 })),
    button: { position: 'bottom-right', offsetX: 24, offsetY: 24, size: 56 },
    menu: { mode: 'speed-dial', shape: 'quarter-circle', direction: 'up-left', radius: 0 }
};
return msg;

msg.payload = {
    actions: [
        { id: 'm-1', label: 'Dashboard', icon: 'pi-home',  payload: 'dashboard' },
        { id: 'm-2', label: 'Settings',  icon: 'pi-cog',   payload: 'settings' },
        { id: 'm-3', label: 'Logout',    icon: 'pi-sign-out', payload: 'logout', background: '#fee2e2', color: '#991b1b' }
    ],
    button: { position: 'top-left', icon: 'pi-bars', label: 'Menu', radius: 12, size: 48 },
    menu: { mode: 'menu', direction: 'down', closeOnSelect: true, overlay: false }
};
return msg;

// Valid, but nothing is updated.
msg.payload = {};
return msg;

// Needs the actions one/two/three from "Three simple actions" (or the editor defaults).
// Omitted values stay unchanged - including the payload.
msg.command = 'patch';
msg.payload = [
    { id: 'two', label: 'Second (patched)', icon: 'pi-bolt', tooltip: 'Patched tooltip' }
];
return msg;

// A patch can change the payload to any native JSON value, including null.
const variants = [
    'text', 123, true, null, { patched: true, list: [1, 2] }, [1, 'a', null]
];
const i = (context.get('i') || 0) % variants.length;
context.set('i', i + 1);
msg.command = 'patch';
msg.payload = [{ id: 'one', payload: variants[i] }];
node.status({ text: JSON.stringify(variants[i]) });
return msg;

msg.command = 'patch';
msg.payload = [
    { id: 'one',   background: '#16a34a', color: '#ffffff', topic: 'patched/one' },
    { id: 'three', background: '#dc262680', color: '#fff' }
];
return msg;

// Empty strings clear colors and topic.
msg.command = 'patch';
msg.payload = [
    { id: 'one',   background: '', color: '', topic: '' },
    { id: 'three', background: '', color: '' }
];
return msg;

const visible = !!context.get('visible');
context.set('visible', !visible);
msg.command = 'patch';
msg.payload = [{ id: 'three', visible }];
node.status({ text: 'three visible: ' + visible });
return msg;

const enabled = !!context.get('enabled');
context.set('enabled', !enabled);
msg.command = 'patch';
msg.payload = [{ id: 'two', enabled }];
node.status({ text: 'two enabled: ' + enabled });
return msg;

// Atomic: either all entries apply, or (unknown/duplicate id) none.
msg.command = 'patch';
msg.payload = [
    { id: 'one',   label: '1', icon: 'pi-check' },
    { id: 'two',   label: '2', enabled: false },
    { id: 'three', label: '3', visible: true, topic: 'many' }
];
return msg;

msg.command = 'remove';
msg.payload = ['two'];          // array of action ids
return msg;

msg.command = 'remove';
msg.payload = ['one', 'three'];
return msg;

// Valid: removes nothing.
msg.command = 'remove';
msg.payload = [];
return msg;

// Restores actions, button, menu and theme from the node's editor settings.
// msg.payload is ignored. No output message is produced.
msg.command = 'reset';
delete msg.payload;
return msg;

// Targeting needs one click on the dial first: the output of the dial is stored by the
// "remember client" function node. The click output carries msg._client.
const last = flow.get('lastClient');
if (!last || !last.socketId) {
    node.warn('Click an action on the dashboard first, so the flow knows your client.');
    return null;
}

// Only the tab with this socketId changes. The shared state is NOT modified.
msg._client = { socketId: last.socketId };
msg.payload = {
    actions: [{ id: 'only-me', label: 'Only for this tab', icon: 'pi-user', payload: 'private' }],
    button: { label: 'Private', background: '#7c3aed' }
};
return msg;

// Targeting needs one click on the dial first: the output of the dial is stored by the
// "remember client" function node. The click output carries msg._client.
const last = flow.get('lastClient');
if (!last || !last.socketId) {
    node.warn('Click an action on the dashboard first, so the flow knows your client.');
    return null;
}

// clientId matches every currently connected socket of that dashboard client.
msg._client = { clientId: last.clientId };
msg.payload = { button: { label: 'My client', background: '#0f766e' } };
return msg;

// Targeting needs one click on the dial first: the output of the dial is stored by the
// "remember client" function node. The click output carries msg._client.
const last = flow.get('lastClient');
if (!last || !last.socketId) {
    node.warn('Click an action on the dashboard first, so the flow knows your client.');
    return null;
}

// Both fields must match.
msg._client = { socketId: last.socketId, clientId: last.clientId };
msg.payload = { menu: { mode: 'menu', direction: 'up' } };
return msg;

// Targeting needs one click on the dial first: the output of the dial is stored by the
// "remember client" function node. The click output carries msg._client.
const last = flow.get('lastClient');
if (!last || !last.socketId) {
    node.warn('Click an action on the dashboard first, so the flow knows your client.');
    return null;
}

// Targeted patch: applied to the actions this client currently has.
msg._client = { socketId: last.socketId };
msg.command = 'patch';
msg.payload = [{ id: 'one', label: 'Patched for me' }];
return msg;

// Targeting needs one click on the dial first: the output of the dial is stored by the
// "remember client" function node. The click output carries msg._client.
const last = flow.get('lastClient');
if (!last || !last.socketId) {
    node.warn('Click an action on the dashboard first, so the flow knows your client.');
    return null;
}

msg._client = { socketId: last.socketId };
msg.command = 'remove';
msg.payload = ['three'];
return msg;

// Targeting needs one click on the dial first: the output of the dial is stored by the
// "remember client" function node. The click output carries msg._client.
const last = flow.get('lastClient');
if (!last || !last.socketId) {
    node.warn('Click an action on the dashboard first, so the flow knows your client.');
    return null;
}

// Puts only this client back to the editor configuration (its own override ends).
msg._client = { socketId: last.socketId };
msg.command = 'reset';
return msg;

// A normal update (no msg._client) applies to all clients and ends every targeted override.
msg.payload = { button: { label: 'Everyone' } };
return msg;

msg.payload = [
    { id: 'dup', payload: 1 },
    { id: 'dup', payload: 2 }
];
// Expected: warning ('Duplicate action id...'), dial unchanged, no output message.
return msg;

// A missing payload is NOT the same as payload: null.
msg.payload = [{ id: 'nopayload', label: 'x' }];
// Expected: warning ('payload is required...'), dial unchanged, no output message.
return msg;

msg.payload = [{ id: 'x', payload: 1, colour: '#fff' }];
// Expected: warning ('Unknown field...'), dial unchanged, no output message.
return msg;

msg.payload = [{ id: 'not valid!', payload: 1 }];
// Expected: warning ('not a valid action id...'), dial unchanged, no output message.
return msg;

msg.payload = { button: { background: 'red' } };
// Expected: warning ('hex color...'), dial unchanged, no output message.
return msg;

msg.payload = { theme: { color: '#abcd' } };
// Expected: warning ('hex color...'), dial unchanged, no output message.
return msg;

msg.payload = { button: { icon: 'plus' } };
// Expected: warning ('PrimeIcon...'), dial unchanged, no output message.
return msg;

msg.payload = { button: { size: 10 } };   // minimum is 11
// Expected: warning ('at least 11...'), dial unchanged, no output message.
return msg;

msg.payload = { button: { size: '56' } };
// Expected: warning ('finite number...'), dial unchanged, no output message.
return msg;

msg.payload = { menu: { gap: NaN } };
// Expected: warning ('finite number...'), dial unchanged, no output message.
return msg;

msg.payload = { button: { position: 'middle' } };
// Expected: warning ('must be one of...'), dial unchanged, no output message.
return msg;

// quarter-circle needs a diagonal direction; the current one is not changed here.
msg.payload = { menu: { shape: 'quarter-circle', direction: 'up' } };
// Expected: warning ('not valid for shape...'), dial unchanged, no output message.
return msg;

// Reset first, then this fails: linear direction "up" does not fit quarter-circle.
msg.payload = { menu: { shape: 'quarter-circle' } };
// Expected: warning ('direction...'), dial unchanged, no output message.
return msg;

msg.payload = { menu: { speed: 'fast' } };
// Expected: warning ('Unknown menu field...'), dial unchanged, no output message.
return msg;

msg.payload = { colors: { primary: '#fff' } };
// Expected: warning ('Unknown payload field...'), dial unchanged, no output message.
return msg;

msg.payload = 'hello';
// Expected: warning ('array or object...'), dial unchanged, no output message.
return msg;

msg.command = 'explode';
msg.payload = [];
// Expected: warning ('Unknown command...'), dial unchanged, no output message.
return msg;

msg.command = 'patch';
msg.payload = [{ id: 'one', label: 'ok' }, { id: 'does-not-exist', label: 'x' }];   // the valid entry is NOT applied
// Expected: warning ('Unknown action id...'), dial unchanged, no output message.
return msg;

msg.command = 'patch';
msg.payload = [{ id: 'one', label: 'a' }, { id: 'one', label: 'b' }];
// Expected: warning ('Duplicate patch id...'), dial unchanged, no output message.
return msg;

msg.command = 'patch';
msg.payload = [{ label: 'no id' }];
// Expected: warning ('id is required...'), dial unchanged, no output message.
return msg;

msg.command = 'patch';
msg.payload = { id: 'one', label: 'x' };
// Expected: warning ('must be an array...'), dial unchanged, no output message.
return msg;

msg.command = 'remove';
msg.payload = ['one', 'does-not-exist'];   // nothing is removed
// Expected: warning ('Unknown action id...'), dial unchanged, no output message.
return msg;

msg.command = 'remove';
msg.payload = [1];
// Expected: warning ('strings...'), dial unchanged, no output message.
return msg;

msg.payload = Array.from({ length: 101 }, (_, i) => ({ id: 'a' + i, payload: i }));
// Expected: warning ('at most 100...'), dial unchanged, no output message.
return msg;

// Targeting needs one click on the dial first: the output of the dial is stored by the
// "remember client" function node. The click output carries msg._client.
const last = flow.get('lastClient');
if (!last || !last.socketId) {
    node.warn('Click an action on the dashboard first, so the flow knows your client.');
    return null;
}
msg._client = { user: { userId: 'someone' } };   // a user alone is not a valid target
msg.payload = { button: { label: 'x' } };
// Expected: warning ('target...'), dial unchanged, no output message.
return msg;

msg._client = { socketId: 'does-not-exist' };
msg.payload = { button: { label: 'x' } };
// Expected: warning ('target...'), dial unchanged, no output message.
return msg;

// Stores the client of the last click for the targeting examples (section 6).
if (msg._client) flow.set('lastClient', msg._client);
return msg;
